@pytest.mark.parametrize('tamper', ['reference', 'type', 'reason', 'missing', 'suppressed'])
def test_restore_rejects_forged_completed_move_interruption(interrupted_return_session: LocalGameSession, tamper: str) -> None:
    payload = deepcopy(interrupted_return_session.lifecycle.to_payload())
    events = payload['decisions']['event_log']
    terminal = next((e for e in events if e['event_type'] == 'mission_action_interrupted'))
    terminal_payload = cast(dict[str, JsonValue], terminal['payload'])
    if tamper == 'reference':
        terminal_payload['source_evidence_event_id'] = 'event:missing'
    elif tamper == 'type':
        terminal_payload['source_evidence_event_type'] = 'movement_activation_completed'
    elif tamper == 'reason':
        terminal_payload['interrupted_reason'] = 'unit_left_battlefield'
    elif tamper == 'missing':
        del terminal_payload['source_evidence_event_id']
    else:
        terminal['event_type'] = 'forged_unrelated_event'
        terminal['payload'] = {}
        action = payload['state']['mission_action_states'][-1]
        action['status'] = 'started'
        action['interrupted_reason'] = None
    with pytest.raises(GameLifecycleError, match='continued after' if tamper == 'suppressed' else None):
        GameLifecycle.from_payload(payload)

@pytest.mark.parametrize(('tamper', 'diagnostic'), [('missing', 'completion boundary lacks one'), ('unknown_record', 'canonical boundary event does not identify exactly one stored record'), ('source', 'canonical boundary event does not identify exactly one stored record'), ('phase', 'canonical boundary event does not identify exactly one stored record'), ('after_terminal', 'objective boundary event ordering')])
def test_secondary_completion_requires_authentic_ordered_boundary(completed_secondary_session: LocalGameSession, tamper: str, diagnostic: str) -> None:
    payload = deepcopy(completed_secondary_session.lifecycle.to_payload())
    events = payload['decisions']['event_log']
    turn_record_ids = {row['record_id'] for row in payload['state']['objective_control_records'] if row['timing'] == 'turn_end'}
    boundary = next((event for event in events if event['event_type'] == 'end_boundary_objective_control_determined' and isinstance(event['payload'], dict) and (event['payload'].get('record_ids') == sorted(turn_record_ids))))
    boundary_payload = cast(dict[str, JsonValue], boundary['payload'])
    if tamper == 'missing':
        boundary['event_type'] = 'forged_unrelated_event'
    elif tamper == 'unknown_record':
        boundary_payload['record_ids'] = ['record:unknown']
    elif tamper == 'source':
        boundary_payload['source_rule_id'] = 'forged-source'
    elif tamper == 'phase':
        boundary_payload['phase'] = 'shooting'
    else:
        terminal = next((e for e in events if e['event_type'] == 'mission_action_completed'))
        boundary['event_type'], terminal['event_type'] = (terminal['event_type'], boundary['event_type'])
        boundary['payload'], terminal['payload'] = (terminal['payload'], boundary['payload'])
    with pytest.raises(GameLifecycleError, match=diagnostic):
        GameLifecycle.from_payload(payload)

@pytest.mark.parametrize(('tamper', 'diagnostic'), [('failed_type', 'terminal event authentication'), ('completed_type', 'terminal event authentication'), ('state', 'terminal event state'), ('game', 'event battle context'), ('round', 'event battle context'), ('phase', 'interruption precedes its start phase'), ('player', 'event player'), ('source', 'terminal source identity'), ('missing', 'terminal event authentication'), ('duplicate', 'terminal event authentication'), ('before_start', 'terminal event ordering')])
def test_secondary_terminal_authenticates_persisted_state_and_context(interrupted_secondary_return_session: LocalGameSession, tamper: str, diagnostic: str) -> None:
    payload = deepcopy(interrupted_secondary_return_session.lifecycle.to_payload())
    events = payload['decisions']['event_log']
    terminal = next((e for e in events if e['event_type'] == 'mission_action_interrupted'))
    terminal_payload = cast(dict[str, JsonValue], terminal['payload'])
    if tamper == 'failed_type':
        terminal['event_type'] = 'mission_action_completion_failed'
    elif tamper == 'completed_type':
        terminal['event_type'] = 'mission_action_completed'
    elif tamper == 'state':
        nested = cast(dict[str, JsonValue], terminal_payload['mission_action_state'])
        nested['target_id'] = 'forged-target'
    elif tamper == 'game':
        terminal_payload['game_id'] = 'forged-game'
    elif tamper == 'round':
        terminal_payload['battle_round'] = 2
    elif tamper == 'phase':
        terminal_payload['phase'] = 'command'
    elif tamper == 'player':
        terminal_payload['player_id'] = 'player-a'
    elif tamper == 'source':
        terminal_payload['mission_action_id'] = 'forged-source'
    elif tamper == 'missing':
        terminal['event_type'] = 'forged_unrelated_event'
    else:
        replacement = next((e for e in events if e['event_type'] == ('primary_mission_boundary_checkpoint_recorded' if tamper == 'before_start' else 'r77_001_before_move')))
        replacement['event_type'] = terminal['event_type']
        replacement['payload'] = deepcopy(terminal_payload)
        if tamper == 'before_start':
            terminal['event_type'] = 'forged_unrelated_event'
    with pytest.raises(GameLifecycleError, match=diagnostic):
        GameLifecycle.from_payload(payload)

