    for invalid_cargo in (replace(cargo, started_phase_embarked_unit_instance_ids=()), cargo.with_disembarked_unit(passenger.unit_instance_id).with_embarked_unit(passenger.unit_instance_id)):
        denied = resolve_disembark(scenario=scenario, ruleset_descriptor=_ruleset(), cargo_state=invalid_cargo, selection=selection, unit=passenger, transport_placement=transport_placement)
