    absent = resolve_disembark(scenario=_without_unit(scenario, transport.unit_instance_id), ruleset_descriptor=_ruleset(), cargo_state=cargo, selection=selection, unit=passenger, transport_placement=transport_placement)
    assert not absent.is_valid
